# The WordPress family (edjobs::fetch_wordpress_postings(), edjobs 0.21.0, 2026-11-14;
# claude-notes/2026-11-14_wordpress-family/): each registry row, with its own Job_Link, City and
# k12_list_rules.csv rule, against the district's captured page(s). Expected titles are the routine's output,
# checked against each district's old parser (every difference listed in the README).
# Test titles name the parser and the district so the auto-fix issue finds that district's fixtures.
# Generated by claude-notes/2026-11-14_wordpress-family/make_family_test.R.

wordpress_parse <- function(district, fixture) {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  row <- reg[reg$District == district, ]
  expect_equal(nrow(row), 1)
  expect_equal(row$Platform, "WordPress")
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  html <- paste(readLines(fixture, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  r <- parse_wordpress_postings(html, row$Job_Link, row$City, k12_list_rule(rules, district, "List_Start"),
                                  k12_list_rule(rules, district, "List_Stop"), k12_list_rule(rules, district, "Skip_Section"))
  expect_true(all(r$Location == row$City))
  r
}

test_that("parse_wordpress_postings: Ramsay School District #3", {
  r <- wordpress_parse("Ramsay School District #3", test_path("fixtures", "ramsay_employment.html"))
  expect_equal(r$Title, c("Bus Monitor",
      "Para-Professional"))
})

test_that("parse_wordpress_postings: Turner Public Schools", {
  r <- wordpress_parse("Turner Public Schools", test_path("fixtures", "turner_employment.html"))
  expect_equal(r$Title, c("Vo-Ag Teacher – Part-time",
      "Business Teacher – Part-time",
      "Secretary"))
  expect_equal(r$Pay_Min[!is.na(r$Pay_Min)], c(14))
})

