test_that("every WordPress registry row resolves to the family routine", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  for (d in reg$District[reg$Platform == "WordPress"]) expect_equal(edjobs::resolve_scraper_call(d)$fn, "fetch_wordpress_postings", info = d)
  expect_equal(edjobs::resolve_scraper_call("Turner Public Schools")$fn, "fetch_wordpress_postings")
})
